const DICTS: Record<Lang, Dict> = { en: EN, kz: KZ, ru: RU }

type Ctx = { lang: Lang; setLang: (l: Lang) => void; t: (k: string) => string }
const I18nContext = createContext<Ctx>({ lang: "en", setLang: () => {}, t: (k) => k })

const KEY = "qadam.lang"
function initial(): Lang {
  try { const s = localStorage.getItem(KEY) as Lang | null; if (s === "en" || s === "kz" || s === "ru") return s } catch { /* ignore */ }
  return "en" // приоритет — английский
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initial)
  useEffect(() => { document.documentElement.lang = lang }, [lang])
  const setLang = (l: Lang) => { setLangState(l); try { localStorage.setItem(KEY, l) } catch { /* ignore */ } }
  const t = (k: string) => DICTS[lang][k] ?? DICTS.en[k] ?? k
  return <I18nContext.Provider value={{ lang, setLang, t }}>{children}</I18nContext.Provider>
}

export function useI18n() { return useContext(I18nContext) }
